    "content": "<!DOCTYPE html>\n<html lang=\"pl\" data-bs-theme=\"light\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>@ViewData[\"Title\"] - Open.IdentityServer Manager</title>\n    <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" />\n    <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css\" />\n    <style>\n        .sidebar {\n            min-height: calc(100vh - 56px);\n            box-shadow: inset -1px 0 0 rgba(0, 0, 0, .1);\n        }\n        .nav-link.active {\n            font-weight: 600;\n            background-color: rgba(13, 110, 253, 0.1);\n            color: #0d6efd !important;\n            border-radius: 6px;\n        }\n    </style>\n</head>\n<body class=\"bg-body-tertiary\">\n    <nav class=\"navbar navbar-expand-lg navbar-dark bg-dark sticky-top px-3 shadow-sm\">\n        <a class=\"navbar-brand fw-bold d-flex align-items-center gap-2\" href=\"/Admin\">\n            <i class=\"bi bi-shield-lock-fill text-warning fs-5\"></i>\n            <span>Open.IdentityServer Admin</span>\n            <span class=\"badge bg-secondary ms-2 small\">.NET 10 (RCL NuGet)</span>\n        </a>\n        <div class=\"ms-auto d-flex align-items-center gap-3\">\n            <span class=\"text-light small d-none d-sm-inline\">\n                <i class=\"bi bi-person-circle me-1 text-warning\"></i>\n                Admin: <strong>@(User.Identity?.Name ?? \"Administrator\")</strong>\n            </span>\n            <form method=\"post\" action=\"/Admin/Account/Logout\" class=\"m-0\">\n                @Html.AntiForgeryToken()\n                <button type=\"submit\" class=\"btn btn-sm btn-outline-danger d-flex align-items-center gap-1\">\n                    <i class=\"bi bi-box-arrow-right\"></i> Wyloguj\n                </button>\n            </form>\n        </div>\n    </nav>\n\n    <div class=\"container-fluid\">\n        <div class=\"row\">\n            <nav class=\"col-md-3 col-lg-2 d-md-block bg-body sidebar py-3 px-3\">\n                <div class=\"d-flex flex-column gap-1\">\n                    <div class=\"text-uppercase text-secondary fw-semibold small px-2 mb-2\">Konfiguracja OIDC</div>\n                    <a href=\"/Admin\" class=\"nav-link text-body px-2 py-2 d-flex align-items-center gap-2\">\n                        <i class=\"bi bi-speedometer2 text-primary\"></i> Pulpit\n                    </a>\n                    <a href=\"/Admin/Clients\" class=\"nav-link text-body px-2 py-2 d-flex align-items-center gap-2\">\n                        <i class=\"bi bi-laptop text-info\"></i> Klienci (Clients)\n                    </a>\n                    <a href=\"/Admin/ApiScopes\" class=\"nav-link text-body px-2 py-2 d-flex align-items-center gap-2\">\n                        <i class=\"bi bi-key text-warning\"></i> Zakresy API (Scopes)\n                    </a>\n                    <a href=\"/Admin/IdentityResources\" class=\"nav-link text-body px-2 py-2 d-flex align-items-center gap-2\">\n                        <i class=\"bi bi-person-vcard text-success\"></i> Zasoby Tożsamości\n                    </a>\n                    <a href=\"/Admin/Federations\" class=\"nav-link text-body px-2 py-2 d-flex align-items-center justify-content-between\">\n                        <span class=\"d-flex align-items-center gap-2\">\n                            <i class=\"bi bi-diagram-3-fill text-warning\"></i> Federacje OIDC\n                        </span>\n                        <span class=\"badge bg-warning-subtle text-warning border border-warning-subtle small\">Dynamic</span>\n                    </a>\n\n                    <hr class=\"my-3\" />\n                    <div class=\"text-uppercase text-secondary fw-semibold small px-2 mb-2\">Bramka API (Proxy)</div>\n                    <a href=\"/Admin/Gateway\" class=\"nav-link text-body px-2 py-2 d-flex align-items-center justify-content-between\">\n                        <span class=\"d-flex align-items-center gap-2\">\n                            <i class=\"bi bi-router-fill text-info\"></i> Reguły Gateway\n                        </span>\n                        <span class=\"badge bg-info-subtle text-info border border-info-subtle small\">Proxy</span>\n                    </a>\n                    <a href=\"/Admin/Gateway/Test\" class=\"nav-link text-body px-2 py-2 d-flex align-items-center justify-content-between\">\n                        <span class=\"d-flex align-items-center gap-2\">\n                            <i class=\"bi bi-lightning-charge-fill text-warning\"></i> Tester Gateway\n                        </span>\n                        <span class=\"badge bg-warning-subtle text-warning border border-warning-subtle small\">Live</span>\n                    </a>\n\n                    <hr class=\"my-3\" />\n                    <div class=\"text-uppercase text-secondary fw-semibold small px-2 mb-2\">Użytkownicy i Sesje</div>\n                    <a href=\"/Admin/Users\" class=\"nav-link text-body px-2 py-2 d-flex align-items-center gap-2\">\n                        <i class=\"bi bi-people text-primary\"></i> Konta Użytkowników\n                    </a>\n                    <a href=\"/Admin/Grants\" class=\"nav-link text-body px-2 py-2 d-flex align-items-center gap-2\">\n                        <i class=\"bi bi-ticket-perforated text-danger\"></i> Tokeny i Zgody\n                    </a>\n\n                    <hr class=\"my-3\" />\n                    <div class=\"p-2 bg-light rounded-3 border small\">\n                        <div class=\"fw-semibold text-dark\"><i class=\"bi bi-database me-1 text-primary\"></i>Baza danych:</div>\n                        <div class=\"text-muted\">Entity Framework Core</div>\n                        <div class=\"badge bg-primary-subtle text-primary mt-1\">SQLite / PostgreSQL</div>\n                    </div>\n                </div>\n            </nav>\n\n            <main class=\"col-md-9 ms-sm-auto col-lg-10 px-md-4 py-4\">\n                @if (TempData[\"SuccessMessage\"] != null)\n                {\n                    <div class=\"alert alert-success alert-dismissible fade show shadow-sm\" role=\"alert\">\n                        <i class=\"bi bi-check-circle-fill me-2\"></i>@TempData[\"SuccessMessage\"]\n                        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button>\n                    </div>\n                }\n                @if (TempData[\"ErrorMessage\"] != null)\n                {\n                    <div class=\"alert alert-danger alert-dismissible fade show shadow-sm\" role=\"alert\">\n                        <i class=\"bi bi-exclamation-triangle-fill me-2\"></i>@TempData[\"ErrorMessage\"]\n                        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button>\n                    </div>\n                }\n                @RenderBody()\n            </main>\n        </div>\n    </div>\n    <script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js\"></script>\n    @await RenderSectionAsync(\"Scripts\", required: false)\n</body>\n</html>\n"
