    "content": "@page \"/Admin/Account/Login\"\n@model Quorum.Backend.AdminUI.Areas.Admin.Pages.Account.LoginModel\n@{\n    Layout = null;\n    ViewData[\"Title\"] = \"Panel Administratora - Logowanie\";\n}\n<!DOCTYPE html>\n<html lang=\"pl\" data-bs-theme=\"light\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>@ViewData[\"Title\"]</title>\n    <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" />\n    <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css\" />\n    <style>\n        body {\n            background: linear-gradient(135deg, #0f172a 0%, #1e293b 50%, #0f172a 100%);\n            min-height: 100vh;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n        }\n        .admin-card {\n            background: #ffffff;\n            border-radius: 1rem;\n            box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.3), 0 8px 10px -6px rgba(0, 0, 0, 0.3);\n        }\n        .brand-header {\n            background: #0f172a;\n            color: #ffffff;\n            border-top-left-radius: 1rem;\n            border-top-right-radius: 1rem;\n            padding: 2rem 1.5rem 1.5rem 1.5rem;\n            text-align: center;\n        }\n    </style>\n</head>\n<body>\n    <div class=\"container py-4\">\n        <div class=\"row justify-content-center\">\n            <div class=\"col-11 col-sm-9 col-md-7 col-lg-5 col-xl-4\">\n                <div class=\"admin-card border-0 overflow-hidden\">\n                    <div class=\"brand-header\">\n                        <div class=\"d-inline-flex p-3 rounded-circle bg-warning bg-opacity-10 text-warning mb-2 border border-warning border-opacity-25\">\n                            <i class=\"bi bi-shield-lock-fill fs-1\"></i>\n                        </div>\n                        <h4 class=\"fw-bold mb-1\">Quorum Admin Console</h4>\n                        <div class=\"d-flex justify-content-center align-items-center gap-2\">\n                            <span class=\"badge bg-danger text-uppercase fw-semibold\" style=\"letter-spacing: 0.5px;\">Dostęp tylko dla Administratorów</span>\n                        </div>\n                    </div>\n\n                    <div class=\"p-4 p-md-4\">\n                        <div class=\"alert alert-secondary py-2 px-3 small d-flex align-items-center gap-2 mb-3 border-0 bg-light\">\n                            <i class=\"bi bi-info-circle text-primary\"></i>\n                            <span>Dedykowana, odizolowana sesja administracyjna (<code>Quorum.Admin.Auth</code>).</span>\n                        </div>\n\n                        <form method=\"post\" asp-page=\"/Account/Login\" asp-route-returnUrl=\"@Model.ReturnUrl\">\n                            <div asp-validation-summary=\"ModelOnly\" class=\"alert alert-danger py-2 small\" role=\"alert\"></div>\n\n                            <div class=\"mb-3\">\n                                <label asp-for=\"Input.Username\" class=\"form-label fw-semibold small text-secondary\"></label>\n                                <div class=\"input-group\">\n                                    <span class=\"input-group-text bg-light text-muted\"><i class=\"bi bi-person-badge\"></i></span>\n                                    <input asp-for=\"Input.Username\" class=\"form-control\" placeholder=\"admin\" autofocus />\n                                </div>\n                                <span asp-validation-for=\"Input.Username\" class=\"text-danger small\"></span>\n                            </div>\n\n                            <div class=\"mb-3\">\n                                <label asp-for=\"Input.Password\" class=\"form-label fw-semibold small text-secondary\"></label>\n                                <div class=\"input-group\">\n                                    <span class=\"input-group-text bg-light text-muted\"><i class=\"bi bi-key\"></i></span>\n                                    <input asp-for=\"Input.Password\" class=\"form-control\" placeholder=\"••••••••\" />\n                                </div>\n                                <span asp-validation-for=\"Input.Password\" class=\"text-danger small\"></span>\n                            </div>\n\n                            <div class=\"form-check mb-4\">\n                                <input asp-for=\"Input.RememberMe\" class=\"form-check-input\" id=\"adminRememberMe\" />\n                                <label class=\"form-check-label small text-secondary\" for=\"adminRememberMe\">\n                                    Zapamiętaj sesję administratora\n                                </label>\n                            </div>\n\n                            <div class=\"d-grid gap-2\">\n                                <button type=\"submit\" class=\"btn btn-dark py-2 fw-semibold shadow-sm d-flex align-items-center justify-content-center gap-2\">\n                                    <i class=\"bi bi-box-arrow-in-right\"></i>\n                                    <span>Zaloguj do Panelu Admina</span>\n                                </button>\n                            </div>\n                        </form>\n\n                        <div class=\"mt-4 pt-3 border-top text-center\">\n                            <a href=\"/Account/Login\" class=\"text-decoration-none small text-muted d-inline-flex align-items-center gap-1\">\n                                <i class=\"bi bi-arrow-left\"></i> Przejdź do logowania użytkowników (Quorum Backend)\n                            </a>\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"text-center mt-3 text-white-50 small\">\n                    Domyślne konto: <code class=\"text-warning\">admin</code> / <code class=\"text-warning\">Pass123$</code>\n                </div>\n            </div>\n        </div>\n    </div>\n</body>\n</html>\n"
